<?php
namespace App\Http\Controllers;
use App\Models\{Product,Stocktake,Tenant};
use App\Services\RetailQuantity;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{Cache,DB};
class StocktakeController extends Controller {
 public function index(Request $r){$stocktakes=Stocktake::where('tenant_id',$r->user()->tenant_id)->latest()->paginate(20);return view('stocktakes.index',compact('stocktakes'));}
 public function store(Request $r){$data=$r->validate(['note'=>'nullable|string|max:1000']);$tenant=$r->user()->tenant_id;$s=DB::transaction(function()use($r,$data,$tenant){$s=Stocktake::create(['tenant_id'=>$tenant,'created_by'=>$r->user()->id,'number'=>'SO-'.now()->format('Ymd-His'),'note'=>$data['note']??null]);Product::where('tenant_id',$tenant)->where('type','product')->where('manage_stock',true)->where('is_active',true)->each(fn($p)=>$s->items()->create(['product_id'=>$p->id,'system_quantity'=>$p->stock]));return $s;});return redirect()->route('stocktakes.show',$s);}
 public function show(Request $r,Stocktake $stocktake){abort_unless($stocktake->tenant_id===$r->user()->tenant_id,404);$stocktake->load('items.product');return view('stocktakes.show',compact('stocktake'));}
 public function complete(Request $r,Stocktake $stocktake){abort_unless($stocktake->tenant_id===$r->user()->tenant_id,404);abort_if($stocktake->status!=='open',422,'Stock opname sudah selesai.');$data=$r->validate(['counts'=>'required|array','counts.*'=>'required|numeric|min:0|max:1000000000']);DB::transaction(function()use($r,$stocktake,$data){Tenant::whereKey($r->user()->tenant_id)->lockForUpdate()->firstOrFail();$stocktake->load('items.product');foreach($stocktake->items as $line){$count=(float)($data['counts'][$line->id]??-1);abort_if($count<0,422,'Semua produk harus dihitung.');$product=Product::where('tenant_id',$r->user()->tenant_id)->whereKey($line->product_id)->lockForUpdate()->firstOrFail();RetailQuantity::requireWhole($count,$product->allow_fraction);$before=(float)$product->stock;$product->update(['stock'=>$count]);$line->update(['counted_quantity'=>$count]);if(abs($count-$before)>0.0001)$product->stockMovements()->create(['tenant_id'=>$r->user()->tenant_id,'user_id'=>$r->user()->id,'type'=>'adjustment','quantity'=>abs($count-$before),'before_stock'=>$before,'after_stock'=>$count,'note'=>'Stock opname '.$stocktake->number,'reference_type'=>'stocktake','reference_id'=>$stocktake->id]);}$stocktake->update(['status'=>'completed','completed_at'=>now()]);Cache::forget('tenant_'.$r->user()->tenant_id.'_products_pos');});return redirect()->route('stocktakes.show',$stocktake)->with('success','Stock opname selesai dan stok telah direkonsiliasi.');}
}
